#pragma once

namespace pedalboard3::session
{

// Per-patch unique node identity. Integer matches master plan §4.5
// schema (`<NODE id="1">`) and keeps logs human-readable. Generated by
// Patch::nextNodeId() as max(existing) + 1; never reused even after a
// delete-then-add cycle within a session. NodeIds are regenerated on
// patch load — they are session-scoped, not cross-session-stable. Phase
// 4 mappings reference NodeIds within the active patch only.
//
// The sentinel value 0 (`graphIO`) means "graph audio/midi I/O endpoint"
// in PatchConnection — `src == graphIO` is the input side, `dst ==
// graphIO` is the output side.
using NodeId = int;
constexpr NodeId graphIO = 0;

} // namespace pedalboard3::session
